-- c016-v003: যখন কিন্তু উপস্থিত–হই, যাদেরকে যদি অনুমোদন–কর, মধ্য–দিয়ে পত্রের এদেরকে পাঠাব, বহন–করতে – দান তোমাদের প্রতি যিরূশালেমে।
-- c016-v004: যদি কিন্তু যোগ্য হয় – আমিও যেতে, সাথে আমার যাবে।
-- c016-v005: আসব কিন্তু প্রতি তোমাদের, যখন মাকেদনিয়া অতিক্রম–করি; মাকেদনিয়ার কেননা মধ্য–দিয়ে–যাচ্ছি।
-- c016-v006: প্রতি তোমাদের কিন্তু সম্ভবত থাকব, অথবা এবং শীতকাল–কাটাব, যেন তোমরা, আমাকে প্রেরণ–কর, যেখানে যদি যাই।
-- c016-v007: না চাই কেননা, তোমাদেরকে এখন মধ্যে গমনে দেখতে; প্রত্যাশা–করি কেননা, সময় কিছু থাকতে প্রতি তোমাদের, যদি – প্রভু অনুমতি–দেন।
-- c016-v008: থাকব কিন্তু মধ্যে ইফিষে পর্যন্ত – পঞ্চাশত্তমীর।
-- c016-v009: দরজা কেননা আমার খোলা–আছে বড় এবং ফলপ্রদ, এবং বিরোধীরা অনেক।
-- c016-v010: যদি কিন্তু আসে তীমথিয়, দেখো যেন নির্ভয়ে হয় কাছে তোমাদের; – কেননা কাজ প্রভুর করে, যেমন আমিও।
-- c016-v011: না কেউ অতএব তাকে তুচ্ছ–করুক; প্রেরণ–করো কিন্তু তাকে মধ্যে শান্তিতে, যেন আসে কাছে আমার; অপেক্ষা–করছি কেননা তাকে, সাথে – ভাইয়েদের।
-- c016-v012: বিষয়ে কিন্তু আপল্লোর, – ভাইয়ের, অনেক অনুরোধ–করেছি তাকে, যেন আসে কাছে তোমাদের সাথে – ভাইয়েদের; এবং আদৌ না ছিল ইচ্ছা যেন এখন আসে; আসবে কিন্তু যখন সুযোগ–পায়।
-- c016-v013: সতর্ক–থাকো; দাঁড়িয়ে–থাকো মধ্যে – বিশ্বাসে, পুরুষের–মতো–আচরণ–করো, শক্তিশালী–হও।
-- c016-v014: সকল তোমাদের, মধ্যে প্রেমে হোক।
-- c016-v015: অনুরোধ–করছি কিন্তু তোমাদেরকে, ভাইয়েরা, জানো – পরিবারকে স্তেফানার, যে হয় প্রথমফল – আখায়ার, এবং জন্য সেবার – পবিত্রদের, নিযুক্ত–করেছে নিজেদেরকে,
-- c016-v016: যেন এবং তোমরা বশীভূত–হও – এমনদের, এবং সকলকে – সহকর্মীকে এবং পরিশ্রমকারীকে।
-- c016-v017: আনন্দিত–হই কিন্তু উপরে – আগমনে স্তেফানার এবং ফর্তুনাতুসের এবং আখাইকুসের; কারণ – তোমাদের অভাব, এরা পূরণ–করেছে।
-- c016-v018: বিশ্রাম–দিয়েছে কেননা – আমার আত্মাকে এবং – তোমাদের; স্বীকার–করো অতএব – এমনদেরকে।
-- c016-v019: অভিবাদন–করে তোমাদেরকে, – মণ্ডলীসমূহ – এশিয়ার। অভিবাদন–করেন তোমাদেরকে মধ্যে প্রভুতে অনেক, আকুলা এবং প্রিস্কা, সাথে –, অনুসারে বাড়িতে তাদের, মণ্ডলী।
-- c016-v020: অভিবাদন–করে তোমাদেরকে, – ভাইয়েরা সকলে। অভিবাদন–করো পরস্পরকে মধ্যে চুম্বনে পবিত্র।
-- c016-v021: – অভিবাদন, – আমার হাতে পৌলের।
-- c016-v022: যদি কেউ না ভালোবাসে – প্রভুকে, থাকুক অভিশপ্ত। মারানা থা!
-- c016-v023: – অনুগ্রহ – প্রভুর যীশুর সাথে তোমাদের।
-- c016-v024: – প্রেম আমার, সাথে সকলের তোমাদের, মধ্যে খ্রীষ্টে যীশুতে। <আমেন>।

